import type { Metadata } from "next";
import { site, type Lang } from "../data/site.ts";
import { copies } from "../i18n/index.ts";
import { defaultLang, langs, localePath } from "../i18n/paths.ts";

/** Social card images, generated by scripts/og-images.ts; regenerate after changing the hero title or the social description. */
export function socialImage(lang: Lang) {
  return { url: `/og/${lang}.png`, width: 1200, height: 630, type: "image/png", alt: copies[lang].meta.socialImageAlt };
}

/**
 * Every page has a Chinese and an English version: the hreflangs point at each other, and x-default points at the default language (English).
 * A child page's openGraph replaces the parent's wholesale, so every page generates a complete set from here;
 * pages that pass title / description (the legal pages) use them for the social card too, otherwise the home page's social copy is used.
 */
export function pageMetadata({
  lang,
  path,
  title,
  description,
  index = true,
}: {
  lang: Lang;
  /** Page path without the language prefix, such as /privacy/. */
  path: string;
  title?: string;
  description?: string;
  /**
   * false for pages that depend on a login or purchase session (the storefront's order, renewal and account pages):
   * noindex, and no Markdown alternate since they have no Markdown version.
   */
  index?: boolean;
}): Metadata {
  const t = copies[lang];
  const url = localePath(lang, path);
  const socialTitle = title ?? t.meta.socialTitle;
  const socialDescription = description ?? t.meta.socialDescription;
  const image = socialImage(lang);
  return {
    metadataBase: new URL(site.url),
    title: title ?? t.meta.title,
    description: description ?? t.meta.description,
    applicationName: site.name,
    alternates: {
      canonical: url,
      languages: {
        ...Object.fromEntries(langs.map((other) => [copies[other].htmlLang, localePath(other, path)])),
        "x-default": localePath(defaultLang, path),
      },
      ...(index ? { types: { "text/markdown": `/md${url}` } } : {}),
    },
    // Allow search results to show large image previews and full snippets.
    robots: index
      ? {
          index: true,
          follow: true,
          googleBot: { index: true, follow: true, "max-image-preview": "large", "max-snippet": -1 },
        }
      : { index: false, follow: false },
    openGraph: {
      title: socialTitle,
      description: socialDescription,
      type: "website",
      url,
      siteName: site.name,
      locale: t.ogLocale,
      alternateLocale: langs.filter((other) => other !== lang).map((other) => copies[other].ogLocale),
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description: socialDescription,
      images: [image],
    },
  };
}
